CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', addresses jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own profile" ON public.profiles FOR ALL TO authenticated USING(auth.uid()=id) WITH CHECK(auth.uid()=id);
CREATE FUNCTION public.create_mahaa_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END; $$;
CREATE TRIGGER mahaa_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_mahaa_profile();
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('admin','moderator')), PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE FUNCTION public.mahaa_staff() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('admin','moderator')); $$;
CREATE TABLE public.customer_bags (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, cart jsonb NOT NULL DEFAULT '[]', wishlist jsonb NOT NULL DEFAULT '[]');
GRANT SELECT, INSERT, UPDATE ON public.customer_bags TO authenticated; GRANT ALL ON public.customer_bags TO service_role;
ALTER TABLE public.customer_bags ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own bag" ON public.customer_bags FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), items jsonb NOT NULL, address jsonb NOT NULL, total integer NOT NULL CHECK(total>0), status text NOT NULL DEFAULT 'concept_order', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own orders" ON public.orders FOR SELECT TO authenticated USING(auth.uid()=user_id OR public.mahaa_staff());
CREATE TABLE public.reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), product_slug text, display_name text NOT NULL CHECK(length(display_name) BETWEEN 1 AND 100), rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), body text NOT NULL CHECK(length(body) BETWEEN 5 AND 2000), image_path text, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), featured boolean NOT NULL DEFAULT false, verified_purchase boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.reviews TO anon; GRANT SELECT, INSERT, UPDATE ON public.reviews TO authenticated; GRANT ALL ON public.reviews TO service_role;
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Approved reviews" ON public.reviews FOR SELECT TO anon,authenticated USING(status='approved');
CREATE POLICY "Own or staff reviews" ON public.reviews FOR SELECT TO authenticated USING(auth.uid()=user_id OR public.mahaa_staff());
CREATE POLICY "Submit pending review" ON public.reviews FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id AND status='pending' AND featured=false AND verified_purchase=false);
CREATE POLICY "Staff moderation" ON public.reviews FOR UPDATE TO authenticated USING(public.mahaa_staff()) WITH CHECK(public.mahaa_staff());
CREATE TABLE public.contact_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), email text NOT NULL CHECK(length(email)<256), message text NOT NULL CHECK(length(message) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.contact_submissions TO service_role; GRANT SELECT ON public.contact_submissions TO authenticated;
ALTER TABLE public.contact_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff contact inbox" ON public.contact_submissions FOR SELECT TO authenticated USING(public.mahaa_staff());
CREATE TABLE public.newsletter_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE CHECK(length(email)<256), created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.newsletter_subscriptions TO service_role;
ALTER TABLE public.newsletter_subscriptions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.form_rate_limits (key text PRIMARY KEY, count integer NOT NULL DEFAULT 1, window_start timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.form_rate_limits TO service_role;
ALTER TABLE public.form_rate_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.check_form_limit(bucket text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.form_rate_limits(key) VALUES(bucket) ON CONFLICT(key) DO UPDATE SET count=CASE WHEN form_rate_limits.window_start<now()-interval '1 hour' THEN 1 ELSE form_rate_limits.count+1 END, window_start=CASE WHEN form_rate_limits.window_start<now()-interval '1 hour' THEN now() ELSE form_rate_limits.window_start END RETURNING count INTO n; RETURN n<=5; END; $$;
REVOKE ALL ON FUNCTION public.check_form_limit(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.check_form_limit(text) TO service_role;